import{promises as fs}from'node:fs';for(const p of['scripts/build.mjs','assets/atlas.css'])await fs.access(p).catch(()=>{throw new Error(`Eksik: ${p}. Repo kökünde çalıştır.`)});const add=async(f,p,m)=>{let s=await fs.readFile(f,'utf8');if(!s.includes(m)){s+='\n'+await fs.readFile(p,'utf8');await fs.writeFile(f,s)}};await add('scripts/build.mjs','v24-build-patch.txt','V24 ISOLATED AUDIO READER');await add('assets/atlas.css','v24-css-patch.txt','V24 isolated audio reader');await fs.copyFile('pa-audio-reader.js','assets/pa-audio-reader.js');console.log('V24 kuruldu: yalıtılmış sesli makale okuyucu eklendi; başka bir özellik değiştirilmedi.');
